        ClinicalAttentionLevel.parse(attention!!)
    } else {
        ClinicalAttentionLevel.NOTE to ""
    }
    val level = if (severeBp != null) ClinicalAttentionLevel.CRITICAL else parsedLevel
    val isDark = isSystemInDarkTheme()

