/* ================= screen 3 - dating ================= */
const TODAY=Date.UTC(2026,10,1),MON=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const Dm=s=>{const a=s.split('-');return Date.UTC(+a[0],+a[1]-1,+a[2]);};
const iso=ms=>new Date(ms).toISOString().slice(0,10);
const addD=(ms,n)=>ms+n*864e5,dd=(a,b)=>Math.round((a-b)/864e5);
const fmtD=ms=>{const d=new Date(ms);return d.getUTCDate()+' '+MON[d.getUTCMonth()]+' '+d.getUTCFullYear();};
const fmtS=ms=>{const d=new Date(ms);return d.getUTCDate()+' '+MON[d.getUTCMonth()];};
const gaTxt=n=>Math.floor(n/7)+'w '+(n%7)+'d';
const MM={lmp:{t:'LMP',sub:'last menstrual period',key:'LMP',lab:'First day of last period'},ivf:{t:'IVF transfer',sub:'transfer date + embryo day',key:'IVF_TRANSFER',lab:'Embryo transfer date'},
  agreed:{t:'Agreed due date',sub:'no LMP, date already agreed',key:'Clinical',lab:'Agreed due date'},scan:{t:'First-trimester scan',sub:'scan date + age or size',key:'Ultrasound',lab:'Scan date'}};
const MORDER=['lmp','ivf','agreed','scan'];
const crlGa=mm=>Math.round(8.052*Math.sqrt(mm)+23.73);
function scanGaDays(sc){return sc.mode==='ga'?sc.w*7+sc.d:crlGa(sc.crl);}
function calc(m,v){
  if(m==='lmp'&&v.lmp)return{edd:addD(Dm(v.lmp),280)};
  if(m==='ivf'&&v.ivf.date)return{edd:addD(Dm(v.ivf.date),280-(14+v.ivf.day))};
  if(m==='agreed'&&v.agreed)return{edd:Dm(v.agreed)};
  if(m==='scan'&&v.scan.date){const g=scanGaDays(v.scan);return{edd:addD(Dm(v.scan.date),280-g),scanGa:g};}
  return null;
}
const gaNow=edd=>280-dd(edd,TODAY);
const gaShow=edd=>{const g=gaNow(edd);return g<0||g>320?'not in range':gaTxt(g);};
function thr(g){return g<=62?5:g<=111?7:g<=153?10:g<=195?14:21;}
function cmpM(a,b,v){
  const ca=calc(a,v),cb=calc(b,v);if(!ca||!cb)return null;
  const diff=dd(cb.edd,ca.edd),ref=(a==='scan'||b==='scan')?Dm(v.scan.date):TODAY,dm=a==='scan'?b:a;
  const g=280-dd(calc(dm,v).edd,ref),t=thr(g),n=Math.abs(diff);
  const txt=n===0?MM[b].t+' gives the same date as '+MM[a].t:MM[b].t+' is '+n+' day'+(n>1?'s':'')+(diff<0?' earlier':' later')+' than '+MM[a].t;
  return{diff:diff,t:t,g:g,flag:n>t,txt:txt,n:n};
}
function datingSample(){return{lmp:'2026-06-14',ivf:{date:'',day:5},agreed:'',scan:{date:'2026-08-10',mode:'ga',w:9,d:2,crl:25}};}
const getD=(v,k)=>k==='lmp'?v.lmp:k==='ivf'?v.ivf.date:k==='agreed'?v.agreed:v.scan.date;
const setDv=(v,k,x)=>{if(k==='lmp')v.lmp=x;else if(k==='ivf')v.ivf.date=x;else if(k==='agreed')v.agreed=x;else v.scan.date=x;};
function dateField(k,v){
  const val=getD(v,k);
  return '<div class="tile"><div class="lbl">'+MM[k].lab+'</div><input class="txtin" style="margin:4px 0 6px" type="date" value="'+esc(val)+'" data-dt="setd" data-key="'+k+'" aria-label="'+MM[k].lab+'">'+
   '<div class="chips">'+chip('dsh','Today',false,{key:k,n:0})+chip('dsh','−1 wk',false,{key:k,n:-7})+chip('dsh','−1 d',false,{key:k,n:-1})+chip('dsh','+1 d',false,{key:k,n:1})+chip('dsh','+1 wk',false,{key:k,n:7})+'</div></div>';
}
function methodInputs(m,v){
  let h=dateField(m,v);
  if(m==='ivf')h+='<div class="tile"><div class="lbl">Embryo age at transfer</div><div class="chips" style="margin-top:6px">'+[3,5,6].map(d=>chip('eday','Day '+d,v.ivf.day===d,{d:d})).join('')+'</div><div class="ref" style="margin-top:6px">GA at transfer = 14 + embryo day · due = transfer + (280 − that)</div></div>';
  if(m==='scan'){const sc=v.scan;
    h+='<div class="tile"><div class="lbl">Scan measurement</div><div class="chips" style="margin:6px 0">'+chip('smode','Gestational age',sc.mode==='ga',{m:'ga'})+chip('smode','Size (CRL)',sc.mode==='crl',{m:'crl'})+'</div>'+
    (sc.mode==='ga'?'<div class="row" style="gap:12px">'+stp(sc.w,'sw-','sw+','w',{})+stp(sc.d,'sd-','sd+','d',{})+'</div>':'<div class="row" style="gap:12px">'+stp(sc.crl,'sc-','sc+','mm',{})+'<span class="val">≈ '+gaTxt(crlGa(sc.crl))+'</span></div><div class="ref" style="margin-top:6px">CRL to age: Robinson formula (to be confirmed)</div>')+'</div>';}
  return h;
}
function usedOf(s,order){const u=s.use&&calc(s.use,s.v)?s.use:order.find(m=>calc(m,s.v));return u||null;}
function heroH(s,u){
  const c=u?calc(u,s.v):null;
  if(!c)return '<div class="hero"><div class="lbl">Due date (EDD)</div><div class="big">—</div><div class="lbl" style="text-transform:none">Enter a date above</div></div>';
  return '<div class="hero"><div class="lbl">Due date (EDD)</div><div class="big">'+fmtD(c.edd)+'</div><div class="row nw" style="justify-content:space-between;margin-top:6px"><div><div class="lbl">GA today</div><b style="font-size:1.15rem">'+gaShow(c.edd)+'</b></div><div style="text-align:right"><div class="lbl">Based on</div><b>'+MM[u].t+'</b></div></div></div><div class="ref" style="margin:4px 4px 0">Saved as Agreed EDD '+iso(c.edd)+' · dating method '+MM[u].key+'</div>';
}
const patHead='<div class="pad"><div class="tile row nw" style="justify-content:space-between"><div><div class="val">Mona Hassan</div><div class="light">33 y · demographics done</div></div><span class="badge ok">✓ step 1</span></div></div>';
const notesBlk=s=>sec('More',null,moreBtn('more','Dating notes',s.more,'')+(s.more?'<textarea class="txtin" data-in="notes" placeholder="Anything about how the dating was decided">'+esc(s.notes)+'</textarea>':''));
const saveBar=(ok)=>'<div class="bar"><button type="button" class="btn ghost" data-a="noop">Back</button><button type="button" class="btn" data-a="save"'+(ok?'':' disabled')+'>Save patient</button></div>';
const dHandlers={
  setd:(s,val,d)=>{setDv(s.v,d.key,val);},
  dsh:(s,d)=>{const cur=getD(s.v,d.key),base=cur?Dm(cur):TODAY;setDv(s.v,d.key,iso(+d.n===0?TODAY:addD(base,+d.n)));},
  eday:(s,d)=>{s.v.ivf.day=+d.d;},smode:(s,d)=>{s.v.scan.mode=d.m;},
  'sw-':s=>{s.v.scan.w=Math.max(5,s.v.scan.w-1);},'sw+':s=>{s.v.scan.w=Math.min(14,s.v.scan.w+1);},
  'sd-':s=>{s.v.scan.d=(s.v.scan.d+6)%7;},'sd+':s=>{s.v.scan.d=(s.v.scan.d+1)%7;},
  'sc-':s=>{s.v.scan.crl=Math.max(2,s.v.scan.crl-1);},'sc+':s=>{s.v.scan.crl=Math.min(84,s.v.scan.crl+1);},
  more:s=>{s.more=!s.more;},notes:(s,v)=>{s.notes=v;},noop:s=>{},save:s=>{s.toast='Saved: patient registered with Agreed EDD from the chosen method.';},
  use:(s,d)=>{s.use=d.m;}
};
reg('s3a',function(){return{m:'lmp',cross:true,m2:'scan',use:'lmp',v:datingSample(),more:false,notes:'',toast:''};},function(s){
  const o=MORDER.filter(m=>m!==s.m),u=usedOf(s,[s.m,s.m2]);
  let h=ptop('Register patient','Step 2 of 3 · pregnancy dating',true)+patHead;
