  return '<div class="hero"><div class="lbl">Due date (EDD)</div><div class="big">'+fmtD(c.edd)+'</div><div class="row nw" style="justify-content:space-between;margin-top:6px"><div><div class="lbl">GA today</div><b style="font-size:1.15rem">'+gaShow(c.edd)+'</b></div><div style="text-align:right"><div class="lbl">Based on</div><b>'+MM[u].t+'</b></div></div></div><div class="ref" style="margin:4px 4px 0">Saved as Agreed EDD '+iso(c.edd)+' · dating method '+MM[u].key+'</div>';
}
const patHead='<div class="pad"><div class="tile row nw" style="justify-content:space-between"><div><div class="val">Mona Hassan</div><div class="light">33 y · demographics done</div></div><span class="badge ok">✓ step 1</span></div></div>';
const notesBlk=s=>sec('More',null,moreBtn('more','Dating notes',s.more,'')+(s.more?'<textarea class="txtin" data-in="notes" placeholder="Anything about how the dating was decided">'+esc(s.notes)+'</textarea>':''));
const saveBar=(ok)=>'<div class="bar"><button type="button" class="btn ghost" data-a="noop">Back</button><button type="button" class="btn" data-a="save"'+(ok?'':' disabled')+'>Save patient</button></div>';
const dHandlers={
  setd:(s,val,d)=>{setDv(s.v,d.key,val);},
  dsh:(s,d)=>{const cur=getD(s.v,d.key),base=cur?Dm(cur):TODAY;setDv(s.v,d.key,iso(+d.n===0?TODAY:addD(base,+d.n)));},
  eday:(s,d)=>{s.v.ivf.day=+d.d;},smode:(s,d)=>{s.v.scan.mode=d.m;},
  'sw-':s=>{s.v.scan.w=Math.max(5,s.v.scan.w-1);},'sw+':s=>{s.v.scan.w=Math.min(14,s.v.scan.w+1);},
  'sd-':s=>{s.v.scan.d=(s.v.scan.d+6)%7;},'sd+':s=>{s.v.scan.d=(s.v.scan.d+1)%7;},
  'sc-':s=>{s.v.scan.crl=Math.max(2,s.v.scan.crl-1);},'sc+':s=>{s.v.scan.crl=Math.min(84,s.v.scan.crl+1);},
  more:s=>{s.more=!s.more;},notes:(s,v)=>{s.notes=v;},noop:s=>{},save:s=>{s.toast='Saved: patient registered with Agreed EDD from the chosen method.';},
  use:(s,d)=>{s.use=d.m;}
};
reg('s3a',function(){return{m:'lmp',cross:true,m2:'scan',use:'lmp',v:datingSample(),more:false,notes:'',toast:''};},function(s){
  const o=MORDER.filter(m=>m!==s.m),u=usedOf(s,[s.m,s.m2]);
  let h=ptop('Register patient','Step 2 of 3 · pregnancy dating',true)+patHead;
  h+=sec('How is this pregnancy dated?','pick one','<div class="mth">'+MORDER.map(m=>'<button type="button" class="tl2'+(s.m===m?' on':'')+'" aria-pressed="'+(s.m===m)+'" data-a="pm" data-m="'+m+'"><b>'+MM[m].t+'</b><span class="light">'+MM[m].sub+'</span></button>').join('')+'</div><div style="height:10px"></div>'+methodInputs(s.m,s.v));
  h+='<div class="pad">'+heroH(s,u)+'</div>';
  if(!s.cross)h+='<div class="pad" style="padding-top:0"><button type="button" class="btn ghost" style="width:100%" data-a="cross">+ Cross-check with a second method</button></div>';
  else{
    const c=cmpM(s.m,s.m2,s.v);
    h+=sec('Cross-check','second method','<div class="chips" style="margin-bottom:10px">'+o.map(m=>chip('m2',MM[m].t,s.m2===m,{m:m})).join('')+'</div>'+methodInputs(s.m2,s.v));
    const ca=calc(s.m,s.v),cb=calc(s.m2,s.v);
    if(ca&&cb){
      h+=sec('Side by side',c.flag?'methods disagree':'methods agree','<div class="'+(c.flag?'warn':'okbox')+'" style="margin-bottom:10px">'+(c.flag?'<b>'+c.txt+'</b> (limit '+c.t+' days at '+gaTxt(c.g)+'). Re-dating is suggested; the choice below becomes the Agreed EDD.':'<b>'+c.txt+'</b>: within the '+c.t+'-day limit. Either is fine.')+'</div>'+
       '<div class="cmp">'+[s.m,s.m2].map((m,i)=>{const cc=calc(m,s.v),used=u===m;return '<div class="'+(used?'used':'')+'"><span class="lbl">'+MM[m].t+'</span><span class="big">'+fmtD(cc.edd)+'</span><span class="light">GA today <b style="color:var(--txt)">'+gaShow(cc.edd)+'</b></span><span class="light">'+(i===0?'reference':(c.diff===0?'same date':c.n+' d '+(c.diff<0?'earlier':'later')))+'</span>'+
         (used?'<span class="badge ok" style="align-self:flex-start;min-height:48px;display:inline-flex;align-items:center">✓ In use</span>':'<button type="button" class="btn" data-a="use" data-m="'+m+'">Use this one</button>')+'</div>';}).join('')+'</div><p class="note" style="margin:10px 0 0">The date you use is saved as the <b>Agreed EDD</b>. It overrides every other method everywhere in the app.</p>');
    }
    h+='<div class="pad" style="padding-top:0"><button type="button" class="btn ghost" style="width:100%" data-a="uncross">Remove cross-check</button></div>';
  }
  h+=notesBlk(s)+saveBar(!!u);
  return h+toast(s);
},Object.assign({},dHandlers,{
  pm:(s,d)=>{s.m=d.m;if(s.m2===d.m)s.m2=MORDER.find(m=>m!==d.m);s.use=d.m;},
  m2:(s,d)=>{s.m2=d.m;},cross:s=>{s.cross=true;},uncross:s=>{s.cross=false;s.use=s.m;}
}));
reg('s3b',function(){return{open:'scan',use:'lmp',v:datingSample(),more:false,notes:'',toast:''};},function(s){
  const filled=MORDER.filter(m=>calc(m,s.v)),u=usedOf(s,MORDER);
  let h=ptop('Register patient','Step 2 of 3 · pregnancy dating',true)+patHead;
  h+='<div class="pad">'+heroH(s,u)+'</div>';
  if(filled.length>1){
    const es=filled.map(m=>calc(m,s.v).edd),mn=Math.min.apply(null,es),mx=Math.max.apply(null,es);
    const flags=filled.filter(m=>m!==u).map(m=>cmpM(u,m,s.v)).filter(Boolean),bad=flags.filter(f=>f.flag);
    h+=sec('Due dates compared',mx===mn?'identical':(mx-mn)/864e5+' days apart','<div class="axis">'+filled.map((m,i)=>{const e=calc(m,s.v).edd,p=mx===mn?50:12+(e-mn)/(mx-mn)*76;return '<i class="'+(m===u?'u':'')+'" style="left:'+p+'%"></i><span style="left:'+p+'%;top:'+(i%2?'36px':'0')+';color:'+(m===u?'var(--teal)':'var(--txt)')+'">'+MM[m].t.split(' ')[0]+' '+fmtS(e)+'</span>';}).join('')+'</div>'+
     flags.map(f=>'<div class="'+(f.flag?'warn':'okbox')+'" style="margin-top:6px">'+f.txt+(f.flag?' (limit '+f.t+' days at '+gaTxt(f.g)+'). Re-dating suggested.':' - within the '+f.t+'-day limit.')+'</div>').join('')+
     '<p class="note" style="margin:8px 0 0">'+(bad.length?'Choose one with "Use this one" below. ':'')+'The one in use is saved as the Agreed EDD and overrides the others.</p>');
  }
  h+='<div class="sec"><div class="sh">Dating methods<span class="r">fill any, in any order</span></div>'+MORDER.map(m=>{const c=calc(m,s.v),o=s.open===m;
    return '<div class="acc"><button type="button" class="ah" data-a="open" data-m="'+m+'" aria-expanded="'+o+'"><span class="st'+(c?' ok':'')+'"></span><span class="grow"><b class="val">'+MM[m].t+'</b><br><span class="light">'+(c?'Due '+fmtD(c.edd)+' · GA '+gaShow(c.edd):'Not entered')+'</span></span>'+(u===m?'<span class="badge ok">in use</span>':'')+'<span aria-hidden="true">'+(o?'⌃':'⌄')+'</span></button>'+
    (o?'<div class="ab">'+methodInputs(m,s.v)+(c&&u!==m?'<button type="button" class="btn" data-a="use" data-m="'+m+'">Use this one</button>':'')+'</div>':'')+'</div>';}).join('')+'</div>';
  h+=notesBlk(s)+saveBar(!!u);
  return h+toast(s);
},Object.assign({},dHandlers,{open:(s,d)=>{s.open=s.open===d.m?null:d.m;}}));

