/* ================= screen 4 - clinical attention ================= */
const LV={note:'NOTE',alert:'ALERT',critical:'CRITICAL'},LVN={note:'alert',alert:'critical',critical:'note'},LVR={note:0,alert:1,critical:2};
const AL=()=>[{lv:'alert',t:'Previous PPH 2021: crossmatch 2 units before delivery'},{lv:'critical',t:'Penicillin allergy (rash)'},{lv:'note',t:'Rh negative: anti-D at 28 weeks'}];
const AL2=[{lv:'alert',t:'Gestational diabetes on insulin'},{lv:'note',t:'Needs an interpreter (speaks Nubian)'}];
const BP={bp:'168/112',date:'2026-10-28'};
const SUGG=['Allergy: (which drug)','Previous PPH: (year, units)','Rh negative: anti-D at 28 weeks','Previous CS scar: (number)','On anticoagulants: (which)','Needs an interpreter'];
const ser=a=>a.map(x=>'['+LV[x.lv]+'] '+x.t).join('\n');
function parseAl(txt){return txt.split('\n').map(l=>l.trim()).filter(Boolean).map(l=>{const m=l.match(/^(?:\[(critical|alert|warning|note)\]|(critical|alert|warning|note):)\s*(.*)$/i);if(!m)return{lv:'note',t:l};const k=(m[1]||m[2]).toLowerCase();return{lv:k==='warning'?'alert':k,t:m[3]||l};});}
const shortT=t=>{const m=t.split(/[:(]/)[0].trim();return m.length>26?m.slice(0,24)+'…':m;};
const bpLine=()=>'Severe BP '+BP.bp+' on '+BP.date;
const lvTag=lv=>'<span class="lv">'+LV[lv]+'</span>';
const bpBox=()=>'<div class="al bp" role="alert"><span class="lv">AUTO</span><div class="grow"><b>'+bpLine()+'</b><div style="font-size:.74rem;opacity:.85">From the latest visit · cannot be edited here</div></div></div>';
const bySev=a=>a.slice().sort((x,y)=>LVR[y.lv]-LVR[x.lv]);
const PL=[{id:'m',n:'Mona Hassan',tags:'<span class="tag ga">20w 0d</span><span class="tag ob">G4 P2 A1</span><span class="tag bl">O−</span>'},{id:'f',n:'Fatma Ibrahim',tags:'<span class="tag ga">31w 2d</span><span class="tag ob">G2 P1 A0</span><span class="tag bl">A+</span>'}];
function listA(s){
  return PL.map(p=>{const al=p.id==='m'?s.al:AL2,bp=p.id==='m'&&s.bp,o=s.lo[p.id];
    return '<div class="pcard"><div class="row nw" style="justify-content:space-between"><span class="nm">'+p.n+'</span><span class="light">Cairo</span></div><div class="row" style="gap:6px">'+p.tags+'</div>'+
    (bp?'<div class="al bp" style="padding:6px 10px"><b style="font-size:.85rem">'+bpLine()+'</b></div>':'')+
    (al.length?'<div class="al man" style="flex-direction:column;padding:6px 10px"><div class="row nw" style="width:100%">'+lvTag(al[0].lv)+'<span class="grow" style="font-weight:650;font-size:.85rem;'+(o?'':'overflow:hidden;text-overflow:ellipsis;white-space:nowrap')+'">'+esc(al[0].t)+'</span>'+(al.length>1?'<button type="button" class="pill" style="min-height:48px;border:0" data-a="lopen" data-id="'+p.id+'" aria-expanded="'+!!o+'">+ '+(al.length-1)+' more</button>':'')+'</div>'+
      (o?al.slice(1).map(x=>'<div class="row nw" style="width:100%;margin-top:4px">'+lvTag(x.lv)+'<span class="grow" style="font-size:.85rem">'+esc(x.t)+'</span></div>').join(''):'')+'</div>':'')+'</div>';}).join('');
}
function listB(s){
  return PL.map(p=>{const al=bySev(p.id==='m'?s.al:AL2),bp=p.id==='m'&&s.bp,o=s.lo[p.id];
    return '<div class="pcard"><div class="row nw" style="justify-content:space-between"><span class="nm">'+p.n+'</span><span class="light">Cairo</span></div><div class="row" style="gap:6px">'+p.tags+'</div>'+
    '<div class="row" style="gap:8px">'+(bp?'<span class="badge err" style="min-height:2em;font-size:.8rem">● BP '+BP.bp+'</span>':'')+(al.length?'<button type="button" class="pill" style="min-height:48px;border:0" data-a="lopen" data-id="'+p.id+'" aria-expanded="'+!!o+'">⚠ '+al.length+' alert'+(al.length>1?'s':'')+' '+(o?'⌃':'⌄')+'</button>':'')+'</div>'+
    (o?'<div class="al man" style="flex-direction:column">'+al.map(x=>'<div class="row nw" style="width:100%">'+lvTag(x.lv)+'<span class="grow" style="font-size:.85rem">'+esc(x.t)+'</span></div>').join('')+'</div>':'')+'</div>';}).join('');
}
const demoBp=s=>'<div class="pad" style="padding-top:0">'+chip('bp','Demo: latest BP is severe',s.bp,{})+'</div>';
reg('s4a',function(){return{view:'main',bp:true,exp:false,al:AL(),dr:null,lo:{},toast:''};},function(s){
  if(s.view==='edit'){
    return ptop('Clinical attention','Mona Hassan',true)+(s.bp?'<div class="pad">'+bpBox()+'</div>':'')+
     sec('Manual alerts ('+s.dr.length+')','one row each',s.dr.map((x,i)=>'<div class="tile" style="margin-bottom:8px;display:flex;flex-direction:column;gap:8px"><div class="row nw" style="justify-content:space-between"><button type="button" class="chip on" style="background:var(--ambt);border-color:var(--ambt);color:var(--amb)" data-a="lvc" data-i="'+i+'" aria-label="Level '+LV[x.lv]+', tap to change">'+LV[x.lv]+' ⟳</button><span class="row nw" style="gap:0">'+(i>0?'<button type="button" class="stp" style="width:48px;height:48px;justify-content:center;border-radius:12px" data-a="first" data-i="'+i+'" aria-label="Make first" title="Make first">▲</button>':'')+'<button type="button" class="stp" style="width:48px;height:48px;justify-content:center;border-radius:12px;margin-left:6px;color:var(--err)" data-a="del" data-i="'+i+'" aria-label="Remove alert">✕</button></span></div><input class="txtin" data-in="ti" data-i="'+i+'" value="'+esc(x.t)+'" aria-label="Alert text"></div>').join('')+
      '<div class="lbl" style="margin:6px 0">Quick add</div><div class="chips">'+SUGG.map((t,i)=>chip('sug',t.split(':')[0],false,{i:i},'add')).join('')+chip('blank','+ Other alert',false,{},'add')+'</div>')+
     sec('Saved as','one alert per line','<div class="sumbox">'+esc(ser(s.dr))+'</div>')+
     '<div class="bar"><button type="button" class="btn ghost" data-a="back">Cancel</button><button type="button" class="btn" data-a="save">Save alerts</button></div>';
  }
  const al=s.al,f=al[0];
  let h=ptop('Profile','Mona Hassan · G4 P2 A1 · 20w 0d',false)+'<div class="pad" style="display:flex;flex-direction:column;gap:8px">'+(s.bp?bpBox():'');
  if(al.length)h+='<div class="al man" style="flex-direction:column"><div class="row nw" style="width:100%"><button type="button" class="grow" style="background:none;border:0;text-align:left;display:flex;gap:8px;align-items:flex-start;min-height:48px;padding:0;color:inherit" data-a="exp" aria-expanded="'+s.exp+'">'+lvTag(f.lv)+'<span style="font-weight:650">'+esc(f.t)+'</span></button>'+
    (al.length>1?'<button type="button" class="pill" style="min-height:48px;border:0" data-a="exp">'+(s.exp?'Hide':'+ '+(al.length-1)+' more')+' '+(s.exp?'⌃':'⌄')+'</button>':'')+
    '<button type="button" class="stp" style="width:48px;height:48px;justify-content:center;border-radius:12px" data-a="edit" aria-label="Edit clinical alerts">✎</button></div>'+
    (s.exp?'<div style="width:100%;border-top:1px solid var(--ambl);margin-top:4px;padding-top:6px">'+al.slice(1).map(x=>'<div class="row nw" style="margin:4px 0">'+lvTag(x.lv)+'<span class="grow">'+esc(x.t)+'</span></div>').join('')+'</div>':'')+'</div>';
  else h+='<button type="button" class="btn ghost" data-a="edit">+ Add clinical alert</button>';
  h+='</div>'+sec('Same patient on the patient list',null,'<div style="margin:-10px">'+listA(s)+'</div>')+demoBp(s);
  return h+toast(s);
},{
  exp:s=>{s.exp=!s.exp;},edit:s=>{s.dr=s.al.map(x=>Object.assign({},x));s.view='edit';},back:s=>{s.view='main';},
  lvc:(s,d)=>{const x=s.dr[+d.i];x.lv=LVN[x.lv];},first:(s,d)=>{const x=s.dr.splice(+d.i,1)[0];s.dr.unshift(x);},del:(s,d)=>{s.dr.splice(+d.i,1);},
  sug:(s,d)=>{s.dr.push({lv:'alert',t:SUGG[+d.i]});},blank:s=>{s.dr.push({lv:'alert',t:''});},
  ti:(s,v,d)=>{s.dr[+d.i].t=v;},save:s=>{s.al=s.dr.filter(x=>x.t.trim());s.view='main';s.toast='Saved '+s.al.length+' alerts.';},
  lopen:(s,d)=>{s.lo[d.id]=!s.lo[d.id];},bp:s=>{s.bp=!s.bp;}
});
reg('s4b',function(){return{view:'main',bp:true,sel:-1,al:AL(),txt:'',lo:{},toast:''};},function(s){
  if(s.view==='edit'){
    const p=parseAl(s.txt);
    return ptop('Clinical attention','Mona Hassan',true)+(s.bp?'<div class="pad">'+bpBox()+'</div>':'')+
     sec('Alerts','one per line','<div class="chips" style="margin-bottom:10px">'+SUGG.map((t,i)=>chip('q',t.split(':')[0],false,{i:i},'add')).join('')+'</div>'+
      '<textarea class="txtin" style="min-height:130px" data-in="txt" aria-label="Alerts, one per line">'+esc(s.txt)+'</textarea><div class="ref" style="margin-top:4px">Start a line with CRITICAL:, ALERT: or NOTE: to set its level. No prefix = NOTE.</div>')+
     sec('Preview',p.length+' alert'+(p.length===1?'':'s'),bySev(p).map(x=>'<div class="al man" style="margin-bottom:6px">'+lvTag(x.lv)+'<span class="grow">'+esc(x.t)+'</span></div>').join('')||'<span class="light">Nothing yet</span>')+
     '<div class="bar"><button type="button" class="btn ghost" data-a="back">Cancel</button><button type="button" class="btn" data-a="save">Save alerts</button></div>';
  }
  const al=bySev(s.al);
  let h=ptop('Profile','Mona Hassan · G4 P2 A1 · 20w 0d',false)+'<div class="pad"><div class="card" style="padding:12px;display:flex;flex-direction:column;gap:10px"><div class="row nw" style="justify-content:space-between"><b>Clinical attention <span class="badge amb">'+(al.length+(s.bp?1:0))+'</span></b><button type="button" class="stp" style="width:48px;height:48px;justify-content:center;border-radius:12px" data-a="edit" aria-label="Edit clinical alerts">✎</button></div><div class="chips">'+
    (s.bp?'<button type="button" class="chip" style="background:var(--errc);color:var(--onerrc);border-color:var(--err)" data-a="selbp"><b>●</b> BP '+BP.bp+'</button>':'')+
    al.map((x,i)=>'<button type="button" class="chip" style="background:var(--amb);color:var(--ambt);border-color:'+(s.sel===i?'var(--ambt)':'var(--ambl)')+';'+(x.lv==='critical'?'font-weight:800':'')+'" data-a="sel" data-i="'+i+'" aria-pressed="'+(s.sel===i)+'">'+(x.lv==='critical'?'‼ ':x.lv==='alert'?'⚠ ':'')+esc(shortT(x.t))+'</button>').join('')+'</div>'+
    (s.sel===-2?'<div class="al bp">'+'<span class="lv">AUTO</span><div class="grow"><b>'+bpLine()+'</b><div style="font-size:.74rem">From the latest visit</div></div></div>':'')+
    (s.sel>=0&&al[s.sel]?'<div class="al man">'+lvTag(al[s.sel].lv)+'<span class="grow" style="font-weight:650">'+esc(al[s.sel].t)+'</span></div>':'')+
    '<div class="note">Most severe first. Tap a chip to read it in full.</div></div></div>';
  h+=sec('Same patient on the patient list',null,'<div style="margin:-10px">'+listB(s)+'</div>')+demoBp(s);
  return h+toast(s);
},{
  edit:s=>{s.txt=ser(s.al);s.view='edit';},back:s=>{s.view='main';},sel:(s,d)=>{s.sel=s.sel===+d.i?-1:+d.i;},selbp:s=>{s.sel=s.sel===-2?-1:-2;},
  q:(s,d)=>{s.txt+=(s.txt&&!/\n$/.test(s.txt)?'\n':'')+'['+LV.alert+'] '+SUGG[+d.i];},
  txt:(s,v)=>{s.txt=v;},save:s=>{s.al=parseAl(s.txt);s.view='main';s.sel=-1;s.toast='Saved '+s.al.length+' alerts.';},
  lopen:(s,d)=>{s.lo[d.id]=!s.lo[d.id];},bp:s=>{s.bp=!s.bp;}
});

/* ================= screen 5 - delivery plan ================= */
const EDD5=Dm('2027-03-21'),WD=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const HOSPS=['Cleopatra Hospital','Dar Al Fouad Hospital','Al Salam Hospital','Nile Badrawi Hospital'],CONS=['Dr. Sherif Radwan','Dr. Amr Salah','Dr. Heba Fawzy'];
const MODES=['Elective CS','Trial of vaginal birth','Induction of labour','Undecided'];
const BB=['Crossmatch 2 units','Crossmatch 4 units','Cell saver','Platelets on call'],PREC=['NICU booking','Anaesthesia review','ICU / HDU bed','Senior anaesthetist','Anti-D within 72 h'];
const ITAGS=['Delayed cord clamping','Spinal anaesthesia preferred','Family member present','Female staff preferred'];
const DP=()=>({hosp:'Cleopatra Hospital',cons:'Dr. Sherif Radwan',mode:'Elective CS',tw:39,td:0,labour:false,bb:['Crossmatch 2 units'],prec:['NICU booking'],safeNone:false,itags:['Delayed cord clamping'],instr:'Husband to stay with her in recovery.',fee:30000,feeSt:'Quoted',post:'',raw:'Previous CS 2021 (Cleopatra). Wants to discuss tubal ligation at 36 weeks.'});
const money=n=>n.toLocaleString('en-US');
function targetTxt(x){if(x.labour)return'At onset of labour (no fixed date)';const g=x.tw*7+x.td,e=addD(EDD5,-(280-g)),d=new Date(e);return x.tw+'w '+x.td+'d = '+WD[d.getUTCDay()]+' '+fmtD(e);}
const feeTxt=x=>x.fee>0?money(x.fee)+' EGP ('+x.feeSt.toLowerCase()+')':'';
function dec(x){return{where:!!x.hosp,how:!!x.mode&&x.mode!=='Undecided',when:x.labour||!!x.tw,safety:x.bb.length+x.prec.length>0||x.safeNone,cost:x.fee>0&&x.feeSt==='Agreed'};}
function savedLines(x){
  const l=[];if(x.hosp)l.push('Hospital: '+x.hosp);
  if(x.fee>0)l.push(x.feeSt==='Agreed'?'Fees: '+money(x.fee)+' EGP (agreed)':'Fees quoted: '+money(x.fee)+' EGP');
  const pl=[];if(x.mode&&x.mode!=='Undecided')pl.push(x.mode);if(!x.labour||true)pl.push('target '+(x.labour?'at onset of labour':x.tw+'w '+x.td+'d'));
  if(x.cons)pl.push('consultant '+x.cons);if(x.bb.length)pl.push('blood bank: '+x.bb.join(', '));if(x.prec.length)pl.push('precautions: '+x.prec.join(', '));
  const ins=x.itags.concat(x.instr?[x.instr]:[]).join(', ');if(ins)pl.push('instructions: '+ins);
  l.push('Plan: '+pl.join('; '));if(x.post)l.push('Postpartum: '+x.post);if(x.raw)l.push(x.raw);return l.join('\n');
}
const tog=(arr,v)=>{const i=arr.indexOf(v);if(i>=0)arr.splice(i,1);else arr.push(v);};
/* field blocks, shared by both editors */
const fWhere=x=>'<div class="lbl">Hospital</div><div class="chips">'+HOSPS.map(h=>chip('hosp',h,x.hosp===h,{v:h})).join('')+chip('hospO','Other…',!!x.hosp&&HOSPS.indexOf(x.hosp)<0,{})+chip('hosp','Not decided yet',!x.hosp,{v:''})+'</div>'+
  (x.hosp&&HOSPS.indexOf(x.hosp)<0?'<input class="txtin" data-in="hospIn" value="'+esc(x.hosp)+'" aria-label="Hospital name">':'')+
  '<div class="lbl" style="margin-top:6px">Consultant</div><div class="chips">'+CONS.map(h=>chip('cons',h,x.cons===h,{v:h})).join('')+'</div>';
const fHow=x=>'<div class="lbl">Planned mode of delivery</div><div class="chips">'+MODES.map(m=>chip('mode',m,x.mode===m,{v:m})).join('')+'</div>'+
  '<div class="lbl" style="margin-top:6px">Special instructions</div><div class="chips">'+ITAGS.map(m=>chip('itag',m,x.itags.indexOf(m)>=0,{v:m})).join('')+'</div><textarea class="txtin" data-in="instr" aria-label="More instructions" placeholder="Anything else">'+esc(x.instr)+'</textarea>';
const fWhen=x=>'<div class="lbl">Target timing</div><div class="chips">'+[38,39,40].map(w=>chip('tw',w+'w',!x.labour&&x.tw===w&&x.td===0,{w:w})).join('')+chip('labour','At onset of labour',x.labour,{})+'</div>'+
  (x.labour?'':'<div class="row" style="gap:12px">'+stp(x.tw,'tw-','tw+','w',{})+stp(x.td,'td-','td+','d',{})+'</div>')+'<div class="val">'+targetTxt(x)+'</div><div class="ref">Counted from the agreed due date, 21 Mar 2027</div>';
const fSafety=x=>'<div class="lbl">Blood bank</div><div class="chips">'+BB.map(m=>chip('bb',m,x.bb.indexOf(m)>=0,{v:m})).join('')+'</div>'+
  '<div class="lbl" style="margin-top:6px">Hospital precautions</div><div class="chips">'+PREC.map(m=>chip('prec',m+(m.indexOf('Anti-D')===0?'<small>suggested: Rh negative</small>':''),x.prec.indexOf(m)>=0,{v:m})).join('')+'</div>'+
  '<div>'+chip('none','None needed',x.safeNone,{})+'</div>';
const fCost=x=>'<div class="row nw" style="justify-content:space-between"><span class="lbl">Expected fees</span>'+(x.fee>0?stp(money(x.fee),'f-','f+','EGP',{}):'<span class="val">Not set</span>')+'</div>'+
  '<div class="chips">'+[25000,30000,35000,40000].map(v=>chip('fee',money(v),x.fee===v,{v:v})).join('')+chip('fee','Not discussed',x.fee===0,{v:0})+'</div><div class="chips">'+['Quoted','Agreed'].map(m=>chip('fst',m,x.feeSt===m,{v:m})).join('')+'</div><div class="ref">Only "Agreed" fills the Agreed Delivery Fees box; a quote stays in the plan.</div>';
const fPost=x=>'<div class="lbl">Postpartum note</div><textarea class="txtin" data-in="post" aria-label="Postpartum note" placeholder="Filled after delivery">'+esc(x.post)+'</textarea>';
const fRaw=(x,open)=>moreBtn('rawm','Notes saved with the plan',open,'')+(open?'<div class="sumbox">'+esc(savedLines(x))+'</div><div class="lbl" style="margin-top:8px">Other notes (free text, kept as typed)</div><textarea class="txtin" data-in="raw" aria-label="Other notes">'+esc(x.raw)+'</textarea>':'');
const KF=[['Blood group','O−',1],['Gestational age','20w 0d'],['Agreed EDD','2027-03-21'],['Risk','Moderate Risk'],['Presentation','Cephalic'],['Placental site','Anterior']];
const keyFacts=()=>'<div class="facts">'+KF.map(k=>'<div class="tile"><div class="lbl">'+k[0]+'</div><div class="val"'+(k[2]?' style="color:var(--err)"':'')+'>'+k[1]+'</div></div>').join('')+'</div>';
const dHead=(s)=>'<div class="row nw" style="justify-content:space-between;padding:12px 12px 0"><b style="font-size:1.1rem;color:var(--pri)">Delivery planning</b><button type="button" class="stp" style="width:48px;height:48px;justify-content:center;border-radius:12px" data-a="edit" data-t="where" aria-label="Edit delivery plan">✎</button></div>';
const dH={
  hosp:(s,d)=>{s.dr.hosp=d.v;},hospO:s=>{if(HOSPS.indexOf(s.dr.hosp)>=0||!s.dr.hosp)s.dr.hosp=' ';},hospIn:(s,v)=>{s.dr.hosp=v||' ';},cons:(s,d)=>{s.dr.cons=s.dr.cons===d.v?'':d.v;},
  mode:(s,d)=>{s.dr.mode=d.v;},itag:(s,d)=>tog(s.dr.itags,d.v),instr:(s,v)=>{s.dr.instr=v;},
  tw:(s,d)=>{s.dr.tw=+d.w;s.dr.td=0;s.dr.labour=false;},labour:s=>{s.dr.labour=!s.dr.labour;},
  'tw-':s=>{s.dr.tw=Math.max(36,s.dr.tw-1);},'tw+':s=>{s.dr.tw=Math.min(41,s.dr.tw+1);},'td-':s=>{s.dr.td=(s.dr.td+6)%7;},'td+':s=>{s.dr.td=(s.dr.td+1)%7;},
  bb:(s,d)=>{tog(s.dr.bb,d.v);s.dr.safeNone=false;},prec:(s,d)=>{tog(s.dr.prec,d.v);s.dr.safeNone=false;},none:s=>{s.dr.safeNone=!s.dr.safeNone;if(s.dr.safeNone){s.dr.bb=[];s.dr.prec=[];}},
  'f-':s=>{s.dr.fee=Math.max(0,s.dr.fee-1000);},'f+':s=>{s.dr.fee+=1000;},fee:(s,d)=>{s.dr.fee=+d.v;},fst:(s,d)=>{s.dr.feeSt=d.v;},
  post:(s,v)=>{s.dr.post=v;},raw:(s,v)=>{s.dr.raw=v;},rawm:s=>{s.rawOpen=!s.rawOpen;},
  edit:(s,d)=>{s.dr=JSON.parse(JSON.stringify(s.d));s.view='edit';s.open=d.t||'where';s.rawOpen=false;},back:s=>{s.view='main';},
  save:s=>{s.dr.hosp=(s.dr.hosp||'').trim();s.d=s.dr;s.view='main';s.toast='Saved. Hospital, fees and plan boxes updated.';}
};
const rv=(l,v)=>'<div class="lbl" style="padding-top:.25em">'+l+'</div><div class="val">'+(v?esc(v):'<span class="light" style="font-style:italic;color:var(--ambi)">Not set</span>')+'</div>';
const bar5=(ok)=>'<div class="bar"><button type="button" class="btn ghost" data-a="back">Cancel</button><button type="button" class="btn" data-a="save">Save delivery plan</button></div>';
reg('s5a',function(){return{view:'main',d:DP(),dr:null,open:'where',rawOpen:false,toast:''};},function(s){
  if(s.view==='edit'){const x=s.dr;
    return ptop('Delivery plan','Mona Hassan · 20w 0d',true)+
     sec('Where','hospital, consultant',fWhere(x).replace(/<div class="lbl" style="margin-top:6px">/,'<div class="lbl" style="margin-top:10px">'))+sec('How','mode, instructions','<div style="display:flex;flex-direction:column;gap:8px">'+fHow(x)+'</div>')+
     sec('When',null,'<div style="display:flex;flex-direction:column;gap:8px">'+fWhen(x)+'</div>')+sec('Safety','blood bank, precautions','<div style="display:flex;flex-direction:column;gap:8px">'+fSafety(x)+'</div>')+
     sec('Cost',null,'<div style="display:flex;flex-direction:column;gap:10px">'+fCost(x)+'</div>')+sec('After delivery','optional',fPost(x))+sec('More',null,fRaw(x,s.rawOpen))+bar5();
  }
  const x=s.d;
  return ptop('Delivery','Mona Hassan · 20w 0d',false)+dHead()+'<div class="pad">'+keyFacts()+'</div>'+
   sec('Agreed Delivery Hospital',null,'<div class="val">'+(x.hosp?esc(x.hosp):'<span class="light" style="font-style:italic;color:var(--ambi)">Hospital not agreed yet</span>')+'</div>')+
   sec('Agreed Delivery Fees',null,'<div class="val">'+(x.fee>0&&x.feeSt==='Agreed'?money(x.fee)+' <span class="unit">EGP</span>':'<span class="light" style="font-style:italic;color:var(--ambi)">To be agreed'+(x.fee>0?' · quoted '+money(x.fee)+' EGP':'')+'</span>')+'</div>')+
   sec('Delivery Plan',null,'<div class="kv" style="margin:0;border:0;padding:0;background:none">'+rv('Mode',x.mode)+rv('Target',targetTxt(x))+rv('Consultant',x.cons)+rv('Blood bank',x.bb.join(', ')||(x.safeNone?'None needed':''))+rv('Precautions',x.prec.join(', '))+rv('Instructions',x.itags.concat(x.instr?[x.instr]:[]).join(', '))+'</div>')+
   sec('Postpartum Note',null,rv('',x.post).replace('<div class="lbl" style="padding-top:.25em"></div>',''))+toast(s);
},Object.assign({},dH));
const TOP=[['where','Where','hospital · consultant',x=>[x.hosp,x.cons].filter(Boolean).join(' · '),fWhere],['how','How','mode · instructions',x=>[x.mode,x.itags.length+(x.instr?1:0)?(x.itags.length+(x.instr?1:0))+' instruction(s)':''].filter(Boolean).join(' · '),fHow],
 ['when','When','target timing',x=>targetTxt(x),fWhen],['safety','Safety','blood bank · precautions',x=>x.safeNone?'None needed':[x.bb.join(', '),x.prec.join(', ')].filter(Boolean).join(' · '),fSafety],['cost','Cost','expected fees',x=>feeTxt(x),fCost]];
reg('s5b',function(){return{view:'main',d:DP(),dr:null,open:'where',rawOpen:false,toast:''};},function(s){
  if(s.view==='edit'){const x=s.dr,dc=dec(x),n=Object.keys(dc).filter(k=>dc[k]).length;
    return ptop('Delivery plan','Mona Hassan · '+n+' of 5 decided',true)+'<div class="pad">'+TOP.map(t=>{const o=s.open===t[0],ok=dc[t[0]];
      return '<div class="acc"><button type="button" class="ah" data-a="acc" data-t="'+t[0]+'" aria-expanded="'+o+'"><span class="st '+(ok?'ok':'warn')+'"></span><span class="grow"><b class="val">'+t[1]+'</b><br><span class="light">'+(esc(t[3](x))||'<i>Open · '+t[2]+'</i>')+'</span></span><span aria-hidden="true">'+(o?'⌃':'⌄')+'</span></button>'+(o?'<div class="ab">'+t[4](x)+'</div>':'')+'</div>';}).join('')+
      '<div class="acc"><button type="button" class="ah" data-a="acc" data-t="post" aria-expanded="'+(s.open==='post')+'"><span class="st"></span><span class="grow"><b class="val">After delivery</b><br><span class="light">'+(esc(x.post)||'Postpartum note · filled later')+'</span></span><span aria-hidden="true">'+(s.open==='post'?'⌃':'⌄')+'</span></button>'+(s.open==='post'?'<div class="ab">'+fPost(x)+'</div>':'')+'</div>'+
      '<div class="acc" style="padding:0 8px">'+fRaw(x,s.rawOpen)+'</div></div>'+bar5();
  }
  const x=s.d,dc=dec(x),n=Object.keys(dc).filter(k=>dc[k]).length;
  return ptop('Delivery','Mona Hassan · 20w 0d',false)+dHead()+'<div class="pad"><div class="tile"><div class="row nw" style="justify-content:space-between"><b class="val">'+n+' of 5 decided</b><span class="light">tap a topic to edit</span></div><div style="height:8px;border-radius:4px;background:var(--line);margin-top:6px"><div style="height:8px;border-radius:4px;background:var(--teal);width:'+n*20+'%"></div></div></div></div>'+
   '<div class="pad" style="padding-top:0">'+keyFacts()+'</div><div class="pad" style="padding-top:0">'+TOP.map(t=>{const ok=dc[t[0]],v=t[3](x);
    return '<button type="button" class="pr" style="margin-bottom:8px" data-a="edit" data-t="'+t[0]+'"><span class="st '+(ok?'ok':'warn')+'"></span><span class="mid"><span class="lbl">'+t[1]+'</span><b style="font-weight:650">'+(v?esc(v):'<span class="light" style="font-style:italic;color:var(--ambi)">Open</span>')+'</b>'+(t[0]==='cost'&&x.fee>0&&x.feeSt==='Quoted'?'<span class="light">quote only, not agreed</span>':'')+'</span><span aria-hidden="true">›</span></button>';}).join('')+
   (x.post?'<div class="tile"><div class="lbl">Postpartum note</div><div class="val">'+esc(x.post)+'</div></div>':'')+'</div>'+toast(s);
},Object.assign({},dH,{acc:(s,d)=>{s.open=s.open===d.t?'':d.t;}}));
})();
</script>
</body>
</html>

toolu_01X4hSb61Kqo3SVabbx9wVoL.content:
/* ================= screen 4 - clinical attention ================= */
const LV={note:'NOTE',alert:'ALERT',critical:'CRITICAL'},LVN={note:'alert',alert:'critical',critical:'note'},LVR={note:0,alert:1,critical:2};
const AL=()=>[{lv:'alert',t:'Previous PPH 2021: crossmatch 2 units before delivery'},{lv:'critical',t:'Penicillin allergy (rash)'},{lv:'note',t:'Rh negative: anti-D at 28 weeks'}];
const AL2=[{lv:'alert',t:'Gestational diabetes on insulin'},{lv:'note',t:'Needs an interpreter (speaks Nubian)'}];
const BP={bp:'168/112',date:'2026-10-28'};
const SUGG=['Allergy: (which drug)','Previous PPH: (year, units)','Rh negative: anti-D at 28 weeks','Previous CS scar: (number)','On anticoagulants: (which)','Needs an interpreter'];
const ser=a=>a.map(x=>'['+LV[x.lv]+'] '+x.t).join('\n');
function parseAl(txt){return txt.split('\n').map(l=>l.trim()).filter(Boolean).map(l=>{const m=l.match(/^(?:\[(critical|alert|warning|note)\]|(critical|alert|warning|note):)\s*(.*)$/i);if(!m)return{lv:'note',t:l};const k=(m[1]||m[2]).toLowerCase();return{lv:k==='warning'?'alert':k,t:m[3]||l};});}
const shortT=t=>{const m=t.split(/[:(]/)[0].trim();return m.length>26?m.slice(0,24)+'…':m;};
const bpLine=()=>'Severe BP '+BP.bp+' on '+BP.date;
const lvTag=lv=>'<span class="lv">'+LV[lv]+'</span>';
const bpBox=()=>'<div class="al bp" role="alert"><span class="lv">AUTO</span><div class="grow"><b>'+bpLine()+'</b><div style="font-size:.74rem;opacity:.85">From the latest visit · cannot be edited here</div></div></div>';
const bySev=a=>a.slice().sort((x,y)=>LVR[y.lv]-LVR[x.lv]);
const PL=[{id:'m',n:'Mona Hassan',tags:'<span class="tag ga">20w 0d</span><span class="tag ob">G4 P2 A1</span><span class="tag bl">O−</span>'},{id:'f',n:'Fatma Ibrahim',tags:'<span class="tag ga">31w 2d</span><span class="tag ob">G2 P1 A0</span><span class="tag bl">A+</span>'}];
function listA(s){
  return PL.map(p=>{const al=p.id==='m'?s.al:AL2,bp=p.id==='m'&&s.bp,o=s.lo[p.id];
    return '<div class="pcard"><div class="row nw" style="justify-content:space-between"><span class="nm">'+p.n+'</span><span class="light">Cairo</span></div><div class="row" style="gap:6px">'+p.tags+'</div>'+
    (bp?'<div class="al bp" style="padding:6px 10px"><b style="font-size:.85rem">'+bpLine()+'</b></div>':'')+
    (al.length?'<div class="al man" style="flex-direction:column;padding:6px 10px"><div class="row nw" style="width:100%">'+lvTag(al[0].lv)+'<span class="grow" style="font-weight:650;font-size:.85rem;'+(o?'':'overflow:hidden;text-overflow:ellipsis;white-space:nowrap')+'">'+esc(al[0].t)+'</span>'+(al.length>1?'<button type="button" class="pill" style="min-height:48px;border:0" data-a="lopen" data-id="'+p.id+'" aria-expanded="'+!!o+'">+ '+(al.length-1)+' more</button>':'')+'</div>'+
      (o?al.slice(1).map(x=>'<div class="row nw" style="width:100%;margin-top:4px">'+lvTag(x.lv)+'<span class="grow" style="font-size:.85rem">'+esc(x.t)+'</span></div>').join(''):'')+'</div>':'')+'</div>';}).join('');
}
function listB(s){
  return PL.map(p=>{const al=bySev(p.id==='m'?s.al:AL2),bp=p.id==='m'&&s.bp,o=s.lo[p.id];
    return '<div class="pcard"><div class="row nw" style="justify-content:space-between"><span class="nm">'+p.n+'</span><span class="light">Cairo</span></div><div class="row" style="gap:6px">'+p.tags+'</div>'+
    '<div class="row" style="gap:8px">'+(bp?'<span class="badge err" style="min-height:2em;font-size:.8rem">● BP '+BP.bp+'</span>':'')+(al.length?'<button type="button" class="pill" style="min-height:48px;border:0" data-a="lopen" data-id="'+p.id+'" aria-expanded="'+!!o+'">⚠ '+al.length+' alert'+(al.length>1?'s':'')+' '+(o?'⌃':'⌄')+'</button>':'')+'</div>'+
    (o?'<div class="al man" style="flex-direction:column">'+al.map(x=>'<div class="row nw" style="width:100%">'+lvTag(x.lv)+'<span class="grow" style="font-size:.85rem">'+esc(x.t)+'</span></div>').join('')+'</div>':'')+'</div>';}).join('');
}
const demoBp=s=>'<div class="pad" style="padding-top:0">'+chip('bp','Demo: latest BP is severe',s.bp,{})+'</div>';
reg('s4a',function(){return{view:'main',bp:true,exp:false,al:AL(),dr:null,lo:{},toast:''};},function(s){
  if(s.view==='edit'){
    return ptop('Clinical attention','Mona Hassan',true)+(s.bp?'<div class="pad">'+bpBox()+'</div>':'')+
     sec('Manual alerts ('+s.dr.length+')','one row each',s.dr.map((x,i)=>'<div class="tile" style="margin-bottom:8px;display:flex;flex-direction:column;gap:8px"><div class="row nw" style="justify-content:space-between"><button type="button" class="chip on" style="background:var(--ambt);border-color:var(--ambt);color:var(--amb)" data-a="lvc" data-i="'+i+'" aria-label="Level '+LV[x.lv]+', tap to change">'+LV[x.lv]+' ⟳</button><span class="row nw" style="gap:0">'+(i>0?'<button type="button" class="stp" style="width:48px;height:48px;justify-content:center;border-radius:12px" data-a="first" data-i="'+i+'" aria-label="Make first" title="Make first">▲</button>':'')+'<button type="button" class="stp" style="width:48px;height:48px;justify-content:center;border-radius:12px;margin-left:6px;color:var(--err)" data-a="del" data-i="'+i+'" aria-label="Remove alert">✕</button></span></div><input class="txtin" data-in="ti" data-i="'+i+'" value="'+esc(x.t)+'" aria-label="Alert text"></div>').join('')+
      '<div class="lbl" style="margin:6px 0">Quick add</div><div class="chips">'+SUGG.map((t,i)=>chip('sug',t.split(':')[0],false,{i:i},'add')).join('')+chip('blank','+ Other alert',false,{},'add')+'</div>')+
     sec('Saved as','one alert per line','<div class="sumbox">'+esc(ser(s.dr))+'</div>')+
     '<div class="bar"><button type="button" class="btn ghost" data-a="back">Cancel</button><button type="button" class="btn" data-a="save">Save alerts</button></div>';
  }
  const al=s.al,f=al[0];
  let h=ptop('Profile','Mona Hassan · G4 P2 A1 · 20w 0d',false)+'<div class="pad" style="display:flex;flex-direction:column;gap:8px">'+(s.bp?bpBox():'');
  if(al.length)h+='<div class="al man" style="flex-direction:column"><div class="row nw" style="width:100%"><button type="button" class="grow" style="background:none;border:0;text-align:left;display:flex;gap:8px;align-items:flex-start;min-height:48px;padding:0;color:inherit" data-a="exp" aria-expanded="'+s.exp+'">'+lvTag(f.lv)+'<span style="font-weight:650">'+esc(f.t)+'</span></button>'+
    (al.length>1?'<button type="button" class="pill" style="min-height:48px;border:0" data-a="exp">'+(s.exp?'Hide':'+ '+(al.length-1)+' more')+' '+(s.exp?'⌃':'⌄')+'</button>':'')+
    '<button type="button" class="stp" style="width:48px;height:48px;justify-content:center;border-radius:12px" data-a="edit" aria-label="Edit clinical alerts">✎</button></div>'+
    (s.exp?'<div style="width:100%;border-top:1px solid var(--ambl);margin-top:4px;padding-top:6px">'+al.slice(1).map(x=>'<div class="row nw" style="margin:4px 0">'+lvTag(x.lv)+'<span class="grow">'+esc(x.t)+'</span></div>').join('')+'</div>':'')+'</div>';
  else h+='<button type="button" class="btn ghost" data-a="edit">+ Add clinical alert</button>';
  h+='</div>'+sec('Same patient on the patient list',null,'<div style="margin:-10px">'+listA(s)+'</div>')+demoBp(s);
  return h+toast(s);
},{
  exp:s=>{s.exp=!s.exp;},edit:s=>{s.dr=s.al.map(x=>Object.assign({},x));s.view='edit';},back:s=>{s.view='main';},
  lvc:(s,d)=>{const x=s.dr[+d.i];x.lv=LVN[x.lv];},first:(s,d)=>{const x=s.dr.splice(+d.i,1)[0];s.dr.unshift(x);},del:(s,d)=>{s.dr.splice(+d.i,1);},
  sug:(s,d)=>{s.dr.push({lv:'alert',t:SUGG[+d.i]});},blank:s=>{s.dr.push({lv:'alert',t:''});},
  ti:(s,v,d)=>{s.dr[+d.i].t=v;},save:s=>{s.al=s.dr.filter(x=>x.t.trim());s.view='main';s.toast='Saved '+s.al.length+' alerts.';},
  lopen:(s,d)=>{s.lo[d.id]=!s.lo[d.id];},bp:s=>{s.bp=!s.bp;}
});
reg('s4b',function(){return{view:'main',bp:true,sel:-1,al:AL(),txt:'',lo:{},toast:''};},function(s){
  if(s.view==='edit'){
    const p=parseAl(s.txt);
    return ptop('Clinical attention','Mona Hassan',true)+(s.bp?'<div class="pad">'+bpBox()+'</div>':'')+
     sec('Alerts','one per line','<div class="chips" style="margin-bottom:10px">'+SUGG.map((t,i)=>chip('q',t.split(':')[0],false,{i:i},'add')).join('')+'</div>'+
      '<textarea class="txtin" style="min-height:130px" data-in="txt" aria-label="Alerts, one per line">'+esc(s.txt)+'</textarea><div class="ref" style="margin-top:4px">Start a line with CRITICAL:, ALERT: or NOTE: to set its level. No prefix = NOTE.</div>')+
     sec('Preview',p.length+' alert'+(p.length===1?'':'s'),bySev(p).map(x=>'<div class="al man" style="margin-bottom:6px">'+lvTag(x.lv)+'<span class="grow">'+esc(x.t)+'</span></div>').join('')||'<span class="light">Nothing yet</span>')+
     '<div class="bar"><button type="button" class="btn ghost" data-a="back">Cancel</button><button type="button" class="btn" data-a="save">Save alerts</button></div>';
  }
  const al=bySev(s.al);
  let h=ptop('Profile','Mona Hassan · G4 P2 A1 · 20w 0d',false)+'<div class="pad"><div class="card" style="padding:12px;display:flex;flex-direction:column;gap:10px"><div class="row nw" style="justify-content:space-between"><b>Clinical attention <span class="badge amb">'+(al.length+(s.bp?1:0))+'</span></b><button type="button" class="stp" style="width:48px;height:48px;justify-content:center;border-radius:12px" data-a="edit" aria-label="Edit clinical alerts">✎</button></div><div class="chips">'+
    (s.bp?'<button type="button" class="chip" style="background:var(--errc);color:var(--onerrc);border-color:var(--err)" data-a="selbp"><b>●</b> BP '+BP.bp+'</button>':'')+
    al.map((x,i)=>'<button type="button" class="chip" style="background:var(--amb);color:var(--ambt);border-color:'+(s.sel===i?'var(--ambt)':'var(--ambl)')+';'+(x.lv==='critical'?'font-weight:800':'')+'" data-a="sel" data-i="'+i+'" aria-pressed="'+(s.sel===i)+'">'+(x.lv==='critical'?'‼ ':x.lv==='alert'?'⚠ ':'')+esc(shortT(x.t))+'</button>').join('')+'</div>'+
    (s.sel===-2?'<div class="al bp">'+'<span class="lv">AUTO</span><div class="grow"><b>'+bpLine()+'</b><div style="font-size:.74rem">From the latest visit</div></div></div>':'')+
    (s.sel>=0&&al[s.sel]?'<div class="al man">'+lvTag(al[s.sel].lv)+'<span class="grow" style="font-weight:650">'+esc(al[s.sel].t)+'</span></div>':'')+
    '<div class="note">Most severe first. Tap a chip to read it in full.</div></div></div>';
  h+=sec('Same patient on the patient list',null,'<div style="margin:-10px">'+listB(s)+'</div>')+demoBp(s);
  return h+toast(s);
},{
  edit:s=>{s.txt=ser(s.al);s.view='edit';},back:s=>{s.view='main';},sel:(s,d)=>{s.sel=s.sel===+d.i?-1:+d.i;},selbp:s=>{s.sel=s.sel===-2?-1:-2;},
  q:(s,d)=>{s.txt+=(s.txt&&!/\n$/.test(s.txt)?'\n':'')+'['+LV.alert+'] '+SUGG[+d.i];},
  txt:(s,v)=>{s.txt=v;},save:s=>{s.al=parseAl(s.txt);s.view='main';s.sel=-1;s.toast='Saved '+s.al.length+' alerts.';},
  lopen:(s,d)=>{s.lo[d.id]=!s.lo[d.id];},bp:s=>{s.bp=!s.bp;}
});

/* ================= screen 5 - delivery plan ================= */
const EDD5=Dm('2027-03-21'),WD=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const HOSPS=['Cleopatra Hospital','Dar Al Fouad Hospital','Al Salam Hospital','Nile Badrawi Hospital'],CONS=['Dr. Sherif Radwan','Dr. Amr Salah','Dr. Heba Fawzy'];
const MODES=['Elective CS','Trial of vaginal birth','Induction of labour','Undecided'];
const BB=['Crossmatch 2 units','Crossmatch 4 units','Cell saver','Platelets on call'],PREC=['NICU booking','Anaesthesia review','ICU / HDU bed','Senior anaesthetist','Anti-D within 72 h'];
const ITAGS=['Delayed cord clamping','Spinal anaesthesia preferred','Family member present','Female staff preferred'];
const DP=()=>({hosp:'Cleopatra Hospital',cons:'Dr. Sherif Radwan',mode:'Elective CS',tw:39,td:0,labour:false,bb:['Crossmatch 2 units'],prec:['NICU booking'],safeNone:false,itags:['Delayed cord clamping'],instr:'Husband to stay with her in recovery.',fee:30000,feeSt:'Quoted',post:'',raw:'Previous CS 2021 (Cleopatra). Wants to discuss tubal ligation at 36 weeks.'});
const money=n=>n.toLocaleString('en-US');
function targetTxt(x){if(x.labour)return'At onset of labour (no fixed date)';const g=x.tw*7+x.td,e=addD(EDD5,-(280-g)),d=new Date(e);return x.tw+'w '+x.td+'d = '+WD[d.getUTCDay()]+' '+fmtD(e);}
const feeTxt=x=>x.fee>0?money(x.fee)+' EGP ('+x.feeSt.toLowerCase()+')':'';
function dec(x){return{where:!!x.hosp,how:!!x.mode&&x.mode!=='Undecided',when:x.labour||!!x.tw,safety:x.bb.length+x.prec.length>0||x.safeNone,cost:x.fee>0&&x.feeSt==='Agreed'};}
function savedLines(x){
  const l=[];if(x.hosp)l.push('Hospital: '+x.hosp);
  if(x.fee>0)l.push(x.feeSt==='Agreed'?'Fees: '+money(x.fee)+' EGP (agreed)':'Fees quoted: '+money(x.fee)+' EGP');
  const pl=[];if(x.mode&&x.mode!=='Undecided')pl.push(x.mode);if(!x.labour||true)pl.push('target '+(x.labour?'at onset of labour':x.tw+'w '+x.td+'d'));
  if(x.cons)pl.push('consultant '+x.cons);if(x.bb.length)pl.push('blood bank: '+x.bb.join(', '));if(x.prec.length)pl.push('precautions: '+x.prec.join(', '));
  const ins=x.itags.concat(x.instr?[x.instr]:[]).join(', ');if(ins)pl.push('instructions: '+ins);
  l.push('Plan: '+pl.join('; '));if(x.post)l.push('Postpartum: '+x.post);if(x.raw)l.push(x.raw);return l.join('\n');
}
const tog=(arr,v)=>{const i=arr.indexOf(v);if(i>=0)arr.splice(i,1);else arr.push(v);};
/* field blocks, shared by both editors */
const fWhere=x=>'<div class="lbl">Hospital</div><div class="chips">'+HOSPS.map(h=>chip('hosp',h,x.hosp===h,{v:h})).join('')+chip('hospO','Other…',!!x.hosp&&HOSPS.indexOf(x.hosp)<0,{})+chip('hosp','Not decided yet',!x.hosp,{v:''})+'</div>'+
  (x.hosp&&HOSPS.indexOf(x.hosp)<0?'<input class="txtin" data-in="hospIn" value="'+esc(x.hosp)+'" aria-label="Hospital name">':'')+
  '<div class="lbl" style="margin-top:6px">Consultant</div><div class="chips">'+CONS.map(h=>chip('cons',h,x.cons===h,{v:h})).join('')+'</div>';
const fHow=x=>'<div class="lbl">Planned mode of delivery</div><div class="chips">'+MODES.map(m=>chip('mode',m,x.mode===m,{v:m})).join('')+'</div>'+
  '<div class="lbl" style="margin-top:6px">Special instructions</div><div class="chips">'+ITAGS.map(m=>chip('itag',m,x.itags.indexOf(m)>=0,{v:m})).join('')+'</div><textarea class="txtin" data-in="instr" aria-label="More instructions" placeholder="Anything else">'+esc(x.instr)+'</textarea>';
const fWhen=x=>'<div class="lbl">Target timing</div><div class="chips">'+[38,39,40].map(w=>chip('tw',w+'w',!x.labour&&x.tw===w&&x.td===0,{w:w})).join('')+chip('labour','At onset of labour',x.labour,{})+'</div>'+
  (x.labour?'':'<div class="row" style="gap:12px">'+stp(x.tw,'tw-','tw+','w',{})+stp(x.td,'td-','td+','d',{})+'</div>')+'<div class="val">'+targetTxt(x)+'</div><div class="ref">Counted from the agreed due date, 21 Mar 2027</div>';
const fSafety=x=>'<div class="lbl">Blood bank</div><div class="chips">'+BB.map(m=>chip('bb',m,x.bb.indexOf(m)>=0,{v:m})).join('')+'</div>'+
  '<div class="lbl" style="margin-top:6px">Hospital precautions</div><div class="chips">'+PREC.map(m=>chip('prec',m+(m.indexOf('Anti-D')===0?'<small>suggested: Rh negative</small>':''),x.prec.indexOf(m)>=0,{v:m})).join('')+'</div>'+
  '<div>'+chip('none','None needed',x.safeNone,{})+'</div>';
const fCost=x=>'<div class="row nw" style="justify-content:space-between"><span class="lbl">Expected fees</span>'+(x.fee>0?stp(money(x.fee),'f-','f+','EGP',{}):'<span class="val">Not set</span>')+'</div>'+
  '<div class="chips">'+[25000,30000,35000,40000].map(v=>chip('fee',money(v),x.fee===v,{v:v})).join('')+chip('fee','Not discussed',x.fee===0,{v:0})+'</div><div class="chips">'+['Quoted','Agreed'].map(m=>chip('fst',m,x.feeSt===m,{v:m})).join('')+'</div><div class="ref">Only "Agreed" fills the Agreed Delivery Fees box; a quote stays in the plan.</div>';
const fPost=x=>'<div class="lbl">Postpartum note</div><textarea class="txtin" data-in="post" aria-label="Postpartum note" placeholder="Filled after delivery">'+esc(x.post)+'</textarea>';
const fRaw=(x,open)=>moreBtn('rawm','Notes saved with the plan',open,'')+(open?'<div class="sumbox">'+esc(savedLines(x))+'</div><div class="lbl" style="margin-top:8px">Other notes (free text, kept as typed)</div><textarea class="txtin" data-in="raw" aria-label="Other notes">'+esc(x.raw)+'</textarea>':'');
const KF=[['Blood group','O−',1],['Gestational age','20w 0d'],['Agreed EDD','2027-03-21'],['Risk','Moderate Risk'],['Presentation','Cephalic'],['Placental site','Anterior']];
const keyFacts=()=>'<div class="facts">'+KF.map(k=>'<div class="tile"><div class="lbl">'+k[0]+'</div><div class="val"'+(k[2]?' style="color:var(--err)"':'')+'>'+k[1]+'</div></div>').join('')+'</div>';
const dHead=(s)=>'<div class="row nw" style="justify-content:space-between;padding:12px 12px 0"><b style="font-size:1.1rem;color:var(--pri)">Delivery planning</b><button type="button" class="stp" style="width:48px;height:48px;justify-content:center;border-radius:12px" data-a="edit" data-t="where" aria-label="Edit delivery plan">✎</button></div>';
const dH={
  hosp:(s,d)=>{s.dr.hosp=d.v;},hospO:s=>{if(HOSPS.indexOf(s.dr.hosp)>=0||!s.dr.hosp)s.dr.hosp=' ';},hospIn:(s,v)=>{s.dr.hosp=v||' ';},cons:(s,d)=>{s.dr.cons=s.dr.cons===d.v?'':d.v;},
  mode:(s,d)=>{s.dr.mode=d.v;},itag:(s,d)=>tog(s.dr.itags,d.v),instr:(s,v)=>{s.dr.instr=v;},
  tw:(s,d)=>{s.dr.tw=+d.w;s.dr.td=0;s.dr.labour=false;},labour:s=>{s.dr.labour=!s.dr.labour;},
  'tw-':s=>{s.dr.tw=Math.max(36,s.dr.tw-1);},'tw+':s=>{s.dr.tw=Math.min(41,s.dr.tw+1);},'td-':s=>{s.dr.td=(s.dr.td+6)%7;},'td+':s=>{s.dr.td=(s.dr.td+1)%7;},
  bb:(s,d)=>{tog(s.dr.bb,d.v);s.dr.safeNone=false;},prec:(s,d)=>{tog(s.dr.prec,d.v);s.dr.safeNone=false;},none:s=>{s.dr.safeNone=!s.dr.safeNone;if(s.dr.safeNone){s.dr.bb=[];s.dr.prec=[];}},
  'f-':s=>{s.dr.fee=Math.max(0,s.dr.fee-1000);},'f+':s=>{s.dr.fee+=1000;},fee:(s,d)=>{s.dr.fee=+d.v;},fst:(s,d)=>{s.dr.feeSt=d.v;},
  post:(s,v)=>{s.dr.post=v;},raw:(s,v)=>{s.dr.raw=v;},rawm:s=>{s.rawOpen=!s.rawOpen;},
  edit:(s,d)=>{s.dr=JSON.parse(JSON.stringify(s.d));s.view='edit';s.open=d.t||'where';s.rawOpen=false;},back:s=>{s.view='main';},
  save:s=>{s.dr.hosp=(s.dr.hosp||'').trim();s.d=s.dr;s.view='main';s.toast='Saved. Hospital, fees and plan boxes updated.';}
};
const rv=(l,v)=>'<div class="lbl" style="padding-top:.25em">'+l+'</div><div class="val">'+(v?esc(v):'<span class="light" style="font-style:italic;color:var(--ambi)">Not set</span>')+'</div>';
const bar5=(ok)=>'<div class="bar"><button type="button" class="btn ghost" data-a="back">Cancel</button><button type="button" class="btn" data-a="save">Save delivery plan</button></div>';
reg('s5a',function(){return{view:'main',d:DP(),dr:null,open:'where',rawOpen:false,toast:''};},function(s){
  if(s.view==='edit'){const x=s.dr;
    return ptop('Delivery plan','Mona Hassan · 20w 0d',true)+
     sec('Where','hospital, consultant',fWhere(x).replace(/<div class="lbl" style="margin-top:6px">/,'<div class="lbl" style="margin-top:10px">'))+sec('How','mode, instructions','<div style="display:flex;flex-direction:column;gap:8px">'+fHow(x)+'</div>')+
     sec('When',null,'<div style="display:flex;flex-direction:column;gap:8px">'+fWhen(x)+'</div>')+sec('Safety','blood bank, precautions','<div style="display:flex;flex-direction:column;gap:8px">'+fSafety(x)+'</div>')+
     sec('Cost',null,'<div style="display:flex;flex-direction:column;gap:10px">'+fCost(x)+'</div>')+sec('After delivery','optional',fPost(x))+sec('More',null,fRaw(x,s.rawOpen))+bar5();
  }
  const x=s.d;
  return ptop('Delivery','Mona Hassan · 20w 0d',false)+dHead()+'<div class="pad">'+keyFacts()+'</div>'+
   sec('Agreed Delivery Hospital',null,'<div class="val">'+(x.hosp?esc(x.hosp):'<span class="light" style="font-style:italic;color:var(--ambi)">Hospital not agreed yet</span>')+'</div>')+
   sec('Agreed Delivery Fees',null,'<div class="val">'+(x.fee>0&&x.feeSt==='Agreed'?money(x.fee)+' <span class="unit">EGP</span>':'<span class="light" style="font-style:italic;color:var(--ambi)">To be agreed'+(x.fee>0?' · quoted '+money(x.fee)+' EGP':'')+'</span>')+'</div>')+
   sec('Delivery Plan',null,'<div class="kv" style="margin:0;border:0;padding:0;background:none">'+rv('Mode',x.mode)+rv('Target',targetTxt(x))+rv('Consultant',x.cons)+rv('Blood bank',x.bb.join(', ')||(x.safeNone?'None needed':''))+rv('Precautions',x.prec.join(', '))+rv('Instructions',x.itags.concat(x.instr?[x.instr]:[]).join(', '))+'</div>')+
   sec('Postpartum Note',null,rv('',x.post).replace('<div class="lbl" style="padding-top:.25em"></div>',''))+toast(s);
},Object.assign({},dH));
const TOP=[['where','Where','hospital · consultant',x=>[x.hosp,x.cons].filter(Boolean).join(' · '),fWhere],['how','How','mode · instructions',x=>[x.mode,x.itags.length+(x.instr?1:0)?(x.itags.length+(x.instr?1:0))+' instruction(s)':''].filter(Boolean).join(' · '),fHow],
 ['when','When','target timing',x=>targetTxt(x),fWhen],['safety','Safety','blood bank · precautions',x=>x.safeNone?'None needed':[x.bb.join(', '),x.prec.join(', ')].filter(Boolean).join(' · '),fSafety],['cost','Cost','expected fees',x=>feeTxt(x),fCost]];
reg('s5b',function(){return{view:'main',d:DP(),dr:null,open:'where',rawOpen:false,toast:''};},function(s){
  if(s.view==='edit'){const x=s.dr,dc=dec(x),n=Object.keys(dc).filter(k=>dc[k]).length;
    return ptop('Delivery plan','Mona Hassan · '+n+' of 5 decided',true)+'<div class="pad">'+TOP.map(t=>{const o=s.open===t[0],ok=dc[t[0]];
      return '<div class="acc"><button type="button" class="ah" data-a="acc" data-t="'+t[0]+'" aria-expanded="'+o+'"><span class="st '+(ok?'ok':'warn')+'"></span><span class="grow"><b class="val">'+t[1]+'</b><br><span class="light">'+(esc(t[3](x))||'<i>Open · '+t[2]+'</i>')+'</span></span><span aria-hidden="true">'+(o?'⌃':'⌄')+'</span></button>'+(o?'<div class="ab">'+t[4](x)+'</div>':'')+'</div>';}).join('')+
      '<div class="acc"><button type="button" class="ah" data-a="acc" data-t="post" aria-expanded="'+(s.open==='post')+'"><span class="st"></span><span class="grow"><b class="val">After delivery</b><br><span class="light">'+(esc(x.post)||'Postpartum note · filled later')+'</span></span><span aria-hidden="true">'+(s.open==='post'?'⌃':'⌄')+'</span></button>'+(s.open==='post'?'<div class="ab">'+fPost(x)+'</div>':'')+'</div>'+
      '<div class="acc" style="padding:0 8px">'+fRaw(x,s.rawOpen)+'</div></div>'+bar5();
  }
  const x=s.d,dc=dec(x),n=Object.keys(dc).filter(k=>dc[k]).length;
  return ptop('Delivery','Mona Hassan · 20w 0d',false)+dHead()+'<div class="pad"><div class="tile"><div class="row nw" style="justify-content:space-between"><b class="val">'+n+' of 5 decided</b><span class="light">tap a topic to edit</span></div><div style="height:8px;border-radius:4px;background:var(--line);margin-top:6px"><div style="height:8px;border-radius:4px;background:var(--teal);width:'+n*20+'%"></div></div></div></div>'+
   '<div class="pad" style="padding-top:0">'+keyFacts()+'</div><div class="pad" style="padding-top:0">'+TOP.map(t=>{const ok=dc[t[0]],v=t[3](x);
    return '<button type="button" class="pr" style="margin-bottom:8px" data-a="edit" data-t="'+t[0]+'"><span class="st '+(ok?'ok':'warn')+'"></span><span class="mid"><span class="lbl">'+t[1]+'</span><b style="font-weight:650">'+(v?esc(v):'<span class="light" style="font-style:italic;color:var(--ambi)">Open</span>')+'</b>'+(t[0]==='cost'&&x.fee>0&&x.feeSt==='Quoted'?'<span class="light">quote only, not agreed</span>':'')+'</span><span aria-hidden="true">›</span></button>';}).join('')+
   (x.post?'<div class="tile"><div class="lbl">Postpartum note</div><div class="val">'+esc(x.post)+'</div></div>':'')+'</div>'+toast(s);
},Object.assign({},dH,{acc:(s,d)=>{s.open=s.open===d.t?'':d.t;}}));
})();
</script>
</body>
</html>

tool_use_result.content:
/* ================= screen 4 - clinical attention ================= */
const LV={note:'NOTE',alert:'ALERT',critical:'CRITICAL'},LVN={note:'alert',alert:'critical',critical:'note'},LVR={note:0,alert:1,critical:2};
const AL=()=>[{lv:'alert',t:'Previous PPH 2021: crossmatch 2 units before delivery'},{lv:'critical',t:'Penicillin allergy (rash)'},{lv:'note',t:'Rh negative: anti-D at 28 weeks'}];
const AL2=[{lv:'alert',t:'Gestational diabetes on insulin'},{lv:'note',t:'Needs an interpreter (speaks Nubian)'}];
const BP={bp:'168/112',date:'2026-10-28'};
const SUGG=['Allergy: (which drug)','Previous PPH: (year, units)','Rh negative: anti-D at 28 weeks','Previous CS scar: (number)','On anticoagulants: (which)','Needs an interpreter'];
const ser=a=>a.map(x=>'['+LV[x.lv]+'] '+x.t).join('\n');
function parseAl(txt){return txt.split('\n').map(l=>l.trim()).filter(Boolean).map(l=>{const m=l.match(/^(?:\[(critical|alert|warning|note)\]|(critical|alert|warning|note):)\s*(.*)$/i);if(!m)return{lv:'note',t:l};const k=(m[1]||m[2]).toLowerCase();return{lv:k==='warning'?'alert':k,t:m[3]||l};});}
const shortT=t=>{const m=t.split(/[:(]/)[0].trim();return m.length>26?m.slice(0,24)+'…':m;};
const bpLine=()=>'Severe BP '+BP.bp+' on '+BP.date;
const lvTag=lv=>'<span class="lv">'+LV[lv]+'</span>';
const bpBox=()=>'<div class="al bp" role="alert"><span class="lv">AUTO</span><div class="grow"><b>'+bpLine()+'</b><div style="font-size:.74rem;opacity:.85">From the latest visit · cannot be edited here</div></div></div>';
const bySev=a=>a.slice().sort((x,y)=>LVR[y.lv]-LVR[x.lv]);
const PL=[{id:'m',n:'Mona Hassan',tags:'<span class="tag ga">20w 0d</span><span class="tag ob">G4 P2 A1</span><span class="tag bl">O−</span>'},{id:'f',n:'Fatma Ibrahim',tags:'<span class="tag ga">31w 2d</span><span class="tag ob">G2 P1 A0</span><span class="tag bl">A+</span>'}];
function listA(s){
  return PL.map(p=>{const al=p.id==='m'?s.al:AL2,bp=p.id==='m'&&s.bp,o=s.lo[p.id];
    return '<div class="pcard"><div class="row nw" style="justify-content:space-between"><span class="nm">'+p.n+'</span><span class="light">Cairo</span></div><div class="row" style="gap:6px">'+p.tags+'</div>'+
    (bp?'<div class="al bp" style="padding:6px 10px"><b style="font-size:.85rem">'+bpLine()+'</b></div>':'')+
    (al.length?'<div class="al man" style="flex-direction:column;padding:6px 10px"><div class="row nw" style="width:100%">'+lvTag(al[0].lv)+'<span class="grow" style="font-weight:650;font-size:.85rem;'+(o?'':'overflow:hidden;text-overflow:ellipsis;white-space:nowrap')+'">'+esc(al[0].t)+'</span>'+(al.length>1?'<button type="button" class="pill" style="min-height:48px;border:0" data-a="lopen" data-id="'+p.id+'" aria-expanded="'+!!o+'">+ '+(al.length-1)+' more</button>':'')+'</div>'+
      (o?al.slice(1).map(x=>'<div class="row nw" style="width:100%;margin-top:4px">'+lvTag(x.lv)+'<span class="grow" style="font-size:.85rem">'+esc(x.t)+'</span></div>').join(''):'')+'</div>':'')+'</div>';}).join('');
}
function listB(s){
  return PL.map(p=>{const al=bySev(p.id==='m'?s.al:AL2),bp=p.id==='m'&&s.bp,o=s.lo[p.id];
    return '<div class="pcard"><div class="row nw" style="justify-content:space-between"><span class="nm">'+p.n+'</span><span class="light">Cairo</span></div><div class="row" style="gap:6px">'+p.tags+'</div>'+
    '<div class="row" style="gap:8px">'+(bp?'<span class="badge err" style="min-height:2em;font-size:.8rem">● BP '+BP.bp+'</span>':'')+(al.length?'<button type="button" class="pill" style="min-height:48px;border:0" data-a="lopen" data-id="'+p.id+'" aria-expanded="'+!!o+'">⚠ '+al.length+' alert'+(al.length>1?'s':'')+' '+(o?'⌃':'⌄')+'</button>':'')+'</div>'+
